using System;
using System.Collections.Generic;
using System.Linq;
using System.Runtime.InteropServices;
using System.Text.Json;
using Deception.Core;
using Deception.PolyModAdapter;
using Terrain=Polytopia.Data.TerrainData;
using Tech=Polytopia.Data.TechData;
using Tribe=PolytopiaBackendBase.Common.TribeType;
namespace Deception.Tests
{
 public static class WaterMovementTests
 {
  static int Assertions;static List<string> Tests=new();
  static void Check(bool ok,string why){Assertions++;if(!ok)throw new Exception(why);}
  static void Test(string id,Action body){Reset();try{body();Tests.Add(id);}catch(Exception e){throw new Exception(id,e);}}
  static void Reset(){NativeMimicWaterMovement.Clear();NativeRegroupSession.Enabled=true;RecruitmentHooks.Registered=true;NativeRegroupSession.Reads=NativeRegroupSession.ReadyCalls=0;PathFinder.Paths=PathFinder.OptionCalls=0;PathFinder.ThrowPath=PathFinder.CloakFilter=PathFinder.CloakFirst=false;PathFinder.During=null;PathFinder.NativeRoute=null;PathFinder.CachedOptions=null;}
  static (GameState s,UnitState u,PlayerState p) Make(string form="island",Tribe tribe=Tribe.Imperius)
  {
   var s=new GameState();var p=new PlayerState{tribe=tribe};s.Players[1]=p;s.Players[2]=new(){Id=2};
   foreach(Tribe t in Enum.GetValues<Tribe>())s.GameLogicData.Tribes[t]=new();
   var aqua=s.GameLogicData.Tribes[Tribe.Aquarion].techOverrides;aqua[Tech.Type.Fishing]=new(){type=Tech.Type.AquaFishing};aqua[Tech.Type.Sailing]=new(){type=Tech.Type.MarineLife};
   var polar=s.GameLogicData.Tribes[Tribe.Polaris].techOverrides;polar[Tech.Type.Fishing]=new(){type=Tech.Type.Frostwork};polar[Tech.Type.Sailing]=new(){type=Tech.Type.IceFishing};
   var u=new UnitState{type=Enum.Parse<UnitType>(RecruitmentCatalog.Variant(form))};foreach(Terrain.Type t in Enum.GetValues<Terrain.Type>())u.Allowed.Add(new(){type=t});
   s.Map.Tiles[new(0,0)]=new(){unit=u,coordinates=new(0,0)};Add(s,1,0,Terrain.Type.Water);Add(s,2,0,Terrain.Type.Ocean);
   var appearance=new LedgerAppearance(form,new("imperius","default"),new("imperius","default"),new("imperius","default"),5,100,100,false,ApparentConcealment.Visible,-1,Array.Empty<string>());
   s.Rows[1]=new(1,1,true,LedgerActualKind.Mimic,true,appearance,PaidInvestmentKind.Known,3);return(s,u,p);
  }
  static void Add(GameState s,int x,int y,Terrain.Type terrain){s.Map.Tiles[new(x,y)]=new(){coordinates=new(x,y),terrain=terrain};}
  static bool Goes(GameState s,UnitState u,int x,int y=0)=>PathFinder.GetPath(s,u.coordinates,new(x,y),u.Movement,u).Count>0;
  static bool Command(GameState s,WorldCoordinates? destination=null,bool valid=true,MoveCommand? command=null){string error="native";NativeMimicWaterMovement.AfterMoveValid(command??new(){To=destination??new(1,0)},s,ref valid,ref error);return valid;}
  static Il2CppSystem.Collections.Generic.List<WorldCoordinates> Coords(params WorldCoordinates[] cells){var list=new Il2CppSystem.Collections.Generic.List<WorldCoordinates>();list.AddRange(cells);return list;}
  public static int Run(){try{
   Test("WATER-001 safe hook ABI",()=>{var h=new HarmonyLib.Harmony();NativeMimicWaterMovement.Install(h);Check(h.Patched.Count==4,"four hooks");Check(h.Patched.All(m=>m.GetParameters().All(p=>p.ParameterType.Name!="PathFinderSettings")),"unsafe wrapper never hooked");Check(Marshal.SizeOf<WorldCoordinates>()==8,"actual coordinate-shaped blittable fixture");});
   foreach(string form in new[]{"island","warrior","amphibian","transportship","dcp_mimic"})Test("WATER-002 "+form+" requires research",()=>{var(s,u,p)=Make(form);Check(!Goes(s,u,1)&&!Command(s),"nonflying aquatic appearance cannot bypass Fishing");p.Techs.Add(Tech.Type.Fishing);Check(Goes(s,u,1)&&Command(s),"Fishing grants only native-legal shallow");Check(!Goes(s,u,2)&&!Command(s,new(2,0)),"deep still gated");p.Techs.Add(Tech.Type.Sailing);Check(Goes(s,u,2)&&Command(s,new(2,0)),"Sailing opens native-legal deep path");Check(u.health==10&&!u.moved&&!u.attacked&&u.owner==1,"query never edits real state");});
   Test("WATER-003 shallow source cannot leave without Fishing",()=>{var(s,u,p)=Make();s.Map.Tiles[u.coordinates].terrain=Terrain.Type.Water;s.Map.Tiles[new(1,0)].terrain=Terrain.Type.Field;Check(!Goes(s,u,1)&&!Command(s),"leaving water traverses source");Check(PathFinder.GetMoveOptions(s,u.coordinates,4,u).Count==0,"no moves from forbidden source");p.Techs.Add(Tech.Type.Fishing);Check(Goes(s,u,1),"research unsticks without editing occupancy");});
   Test("WATER-004 deep source requires Sailing",()=>{var(s,u,p)=Make();s.Map.Tiles[u.coordinates].terrain=Terrain.Type.Ocean;s.Map.Tiles[new(1,0)].terrain=Terrain.Type.Field;p.Techs.Add(Tech.Type.Fishing);Check(!Goes(s,u,1),"deep source");p.Techs.Add(Tech.Type.Sailing);Check(Goes(s,u,1),"native-legal landing");});
   Test("WATER-005 owner research not observer or birth tribe",()=>{var(s,u,p)=Make();s.Players[2].Techs.Add(Tech.Type.Fishing);p.Techs.Add(Tech.Type.Propaganda);Check(!Goes(s,u,1),"other player and Propaganda don't grant movement");u.owner=2;Check(Goes(s,u,1),"actual owner's tech controls");});
   Test("WATER-006 Aquarion native movement research",()=>{var(s,u,p)=Make(tribe:Tribe.Aquarion);p.Techs.Add(Tech.Type.AquaFishing);Check(!Goes(s,u,1),"AquaFishing itself has no movement unlock");p.Techs.Add(Tech.Type.AquaBase);Check(Goes(s,u,1)&&!Goes(s,u,2),"AquaBase grants actual native shallow movement");p.Techs.Add(Tech.Type.MarineLife);Check(Goes(s,u,2),"MarineLife grants native ocean");});
   Test("WATER-006 Polaris counterparts do not invent movement",()=>{var(s,u,p)=Make(tribe:Tribe.Polaris);p.Techs.UnionWith(new[]{Tech.Type.Frostwork,Tech.Type.IceFishing});Check(!Goes(s,u,1),"no water unlock in native counterpart research");s.Map.Tiles[new(1,0)].terrain=Terrain.Type.Ice;Check(Goes(s,u,1),"native basic ice remains available");});
   Test("WATER-006 flying Mimic native water bypass",()=>{var(s,u,p)=Make("firedragon");Check(Goes(s,u,1)&&Goes(s,u,2)&&Command(s,new(2,0)),"Fly crosses shallow and ocean without research");s.Map.Tiles[u.coordinates].terrain=Terrain.Type.Ocean;Check(Goes(s,u,1),"Fly can leave water without naval research");});
   Test("WATER-007 unusual Sailing-only state follows terrain",()=>{var(s,u,p)=Make();s.Map.Tiles[new(1,0)].terrain=Terrain.Type.Ocean;p.Techs.Add(Tech.Type.Sailing);Check(Goes(s,u,1),"exact deep tech, no invented prerequisite check");s.Map.Tiles[new(1,0)].terrain=Terrain.Type.Water;Check(!Goes(s,u,1),"shallow independently needs Fishing");});
   Test("WATER-008 no native movement invented",()=>{var(s,u,p)=Make(tribe:Tribe.Polaris);p.Techs.UnionWith(new[]{Tech.Type.Frostwork,Tech.Type.IceFishing});u.Allowed.RemoveAll(t=>t.type==Terrain.Type.Water);Check(!Goes(s,u,1),"counterpart research cannot add native-forbidden water");});
   foreach(UnitType trueType in new[]{UnitType.warrior,UnitType.island,UnitType.amphibian,UnitType.firedragon})Test("WATER-009 genuine disguised "+trueType,()=>{var(s,u,p)=Make();u.type=trueType;s.Rows[1]=s.Rows[1] with{Kind=LedgerActualKind.Genuine};Check(Goes(s,u,2)&&Command(s,new(2,0)),"actual genuine movement unchanged");Check(NativeRegroupSession.Reads==0&&NativeRegroupSession.ReadyCalls==0,"ordinary units avoid ledger entirely");});
   Test("WATER-010 source lists immutable and placement untouched",()=>{var(s,u,p)=Make();var source=u.Allowed;var direct=UnitDataExtensions.GetAllowedTerrain(u,s);Check(ReferenceEquals(direct,source)&&source.Any(t=>t.type==Terrain.Type.Water),"exchange/recruitment direct terrain query unchanged");Goes(s,u,1);Check(ReferenceEquals(UnitDataExtensions.GetAllowedTerrain(u,s),source)&&source.Count==9,"movement filter leaves shared native terrain list intact");});
   Test("WATER-011 alternate legal land route",()=>{var(s,u,p)=Make();s.Map.Tiles[new(2,0)].terrain=Terrain.Type.Field;Add(s,0,1,Terrain.Type.Field);Add(s,1,1,Terrain.Type.Field);Add(s,2,1,Terrain.Type.Field);var path=PathFinder.GetPath(s,u.coordinates,new(2,0),4,u);Check(path.Count==5&&!path.Contains(new(1,0)),"filtered native terrain finds legal alternate path");});
   Test("WATER-012 port cannot bypass or form transit bridge",()=>{var(s,u,p)=Make();s.Map.Tiles[new(1,0)].Port=true;s.Map.Tiles[new(2,0)].terrain=Terrain.Type.Field;Check(!Goes(s,u,1)&&!Goes(s,u,2)&&!Command(s,new(2,0)),"source/destination and interior water all checked");Check(!PathFinder.GetMoveOptions(s,u.coordinates,4,u).Contains(new(2,0)),"no deceptive land endpoint beyond unresearched port");});
   Test("WATER-013 native ocean Wetland alternative",()=>{var(s,u,p)=Make();p.Techs.Add(Tech.Type.Fishing);s.Map.Tiles[new(2,0)].Flooded=true;Check(Goes(s,u,2),"native Wetland alternative stays legal without Sailing");u.Allowed.RemoveAll(t=>t.type==Terrain.Type.Wetland);Check(!Goes(s,u,2),"appearance without Wetland terrain cannot borrow the exception");});
   Test("WATER-014 native ice stays ordinary terrain",()=>{var(s,u,p)=Make();s.Map.Tiles[new(1,0)].terrain=Terrain.Type.Ice;Check(Goes(s,u,1),"no water-tech requirement on ice");});
   Test("WATER-015 native denial remains denial",()=>{var(s,u,p)=Make();p.Techs.UnionWith(new[]{Tech.Type.Fishing,Tech.Type.Sailing});bool valid=false;string error="native action spent";NativeMimicWaterMovement.AfterMoveValid(new MoveCommand(),s,ref valid,ref error);Check(!valid&&error=="native action spent"&&NativeRegroupSession.Reads==0,"only veto, no action refresh");});
   Test("WATER-016 options copies preserve order and alias",()=>{var(s,u,p)=Make();Add(s,0,1,Terrain.Type.Field);var original=Coords(new(0,1),new(1,0),new(0,0),new(0,1));PathFinder.CachedOptions=original;var result=PathFinder.GetMoveOptions(s,u.coordinates,4,u);Check(result.SequenceEqual(new[]{new WorldCoordinates(0,1),new(0,0),new(0,1)}),"remove only forbidden options");Check(original.Count==4&&!ReferenceEquals(original,result),"cached original untouched");});
   Test("WATER-017 unrestricted options preserve identity and avoid path probes",()=>{var(s,u,p)=Make();p.Techs.UnionWith(new[]{Tech.Type.Fishing,Tech.Type.Sailing});var original=Coords(new(1,0),new(2,0));PathFinder.CachedOptions=original;Check(ReferenceEquals(PathFinder.GetMoveOptions(s,u.coordinates,4,u),original)&&PathFinder.Paths==0,"no extra work once both researches owned");});
   foreach(string change in new[]{"disabled","unregistered","unowned","missing-row","dead-row","genuine-row","foreign-body","wrong-origin","missing-owner"})Test("WATER-018 "+change,()=>{var(s,u,p)=Make();switch(change){case "disabled":NativeRegroupSession.Enabled=false;break;case "unregistered":RecruitmentHooks.Registered=false;break;case "unowned":s.Owned=false;break;case "missing-row":s.Rows.Clear();break;case "dead-row":s.Rows[1]=s.Rows[1] with{Alive=false};break;case "genuine-row":s.Rows[1]=s.Rows[1] with{Kind=LedgerActualKind.Genuine};break;case "foreign-body":u=new(){type=u.type};break;case "wrong-origin":u.coordinates=new(0,1);break;case "missing-owner":s.Players.Clear();break;}Check(!Goes(s,u,1),"private carrier cannot borrow unsupported/stale native permission");});
   Test("WATER-019 null unit probe stays native",()=>{var(s,u,p)=Make();Check(PathFinder.GetPath(s,new(0,0),new(2,0),4,null).Count==3,"native null-unit terrain probe supported");Check(NativeRegroupSession.Reads==0,"not a private unit");});
   Test("WATER-020 exception restores scoped terrain filter",()=>{var(s,u,p)=Make();PathFinder.ThrowPath=true;bool threw=false;try{Goes(s,u,0);}catch(InvalidOperationException){threw=true;}Check(threw,"native exception preserved");Check(ReferenceEquals(UnitDataExtensions.GetAllowedTerrain(u,s),u.Allowed),"no leaked movement context");});
   Test("WATER-021 nested other-unit context restores outer",()=>{var(s,u,p)=Make();object? output=null;NativeMimicWaterMovement.BeforeOptions(s,u.coordinates,u,out var outer,ref output);var other=new UnitState{type=UnitType.warrior};NativeMimicWaterMovement.BeforeOptions(s,u.coordinates,other,out var inner,ref output);Check(ReferenceEquals(UnitDataExtensions.GetAllowedTerrain(u,s),u.Allowed),"outer not accidentally inherited by inner");NativeMimicWaterMovement.Finished(null,inner);Check(!UnitDataExtensions.GetAllowedTerrain(u,s).Any(t=>t.type==Terrain.Type.Water),"outer restored");NativeMimicWaterMovement.Finished(null,inner);NativeMimicWaterMovement.Finished(null,outer);Check(ReferenceEquals(UnitDataExtensions.GetAllowedTerrain(u,s),u.Allowed),"duplicate finalizer safe");});
   Test("WATER-022 session clear cannot revive scope",()=>{var(s,u,p)=Make();object? output=null;NativeMimicWaterMovement.BeforeOptions(s,u.coordinates,u,out var outer,ref output);NativeMimicWaterMovement.Clear();NativeMimicWaterMovement.Finished(null,outer);Check(ReferenceEquals(UnitDataExtensions.GetAllowedTerrain(u,s),u.Allowed),"old finalizer cannot revive cleared scope");output=Coords(new WorldCoordinates(0,0));NativeMimicWaterMovement.AfterOptions(s,u.coordinates,4,u,outer,ref output);Check(((Il2CppSystem.Collections.Generic.List<WorldCoordinates>)output!).Count==0,"late result rejects expired generation");});
   foreach(string mutation in new[]{"owner","map","session","position","tile"})Test("WATER-023 pending "+mutation+" invalidates",()=>{var(s,u,p)=Make();object? output=null;NativeMimicWaterMovement.BeforeOptions(s,u.coordinates,u,out var scope,ref output);switch(mutation){case "owner":u.owner=2;break;case "map":s.Map=new();break;case "session":s.Owned=false;break;case "position":u.coordinates=new(1,0);break;case "tile":s.Map.Tiles.Clear();break;}output=Coords(new WorldCoordinates(0,0));NativeMimicWaterMovement.AfterOptions(s,new WorldCoordinates(0,0),4,u,scope,ref output);Check(((Il2CppSystem.Collections.Generic.List<WorldCoordinates>)output!).Count==0,"changed native binding rejects result");NativeMimicWaterMovement.Finished(null,scope);});
   foreach(bool first in new[]{true,false})Test("WATER-024 Cloak restriction intersection "+first,()=>{var(s,u,p)=Make("cloak");p.Techs.Add(Tech.Type.Fishing);s.Map.Tiles[new(1,0)].City=true;s.Map.Tiles[new(1,0)].Owner=2;PathFinder.CloakFilter=true;PathFinder.CloakFirst=first;var options=PathFinder.GetMoveOptions(s,u.coordinates,4,u);Check(!options.Contains(new(1,0))&&!options.Contains(new(2,0)),"city and ocean both blocked for either postfix ordering");});
   Test("WATER-025 land hover does not run per-option paths",()=>{var(s,u,p)=Make("warrior");s.Map.Tiles[new(1,0)].terrain=Terrain.Type.Field;s.Map.Tiles[new(2,0)].terrain=Terrain.Type.Field;var options=PathFinder.GetMoveOptions(s,u.coordinates,4,u);Check(options.Count==3&&PathFinder.Paths==0,"ordinary non-Swim land options keep native search");});
   Test("WATER-026 flying hover has no additional paths",()=>{var(s,u,p)=Make("firedragon");var options=PathFinder.GetMoveOptions(s,u.coordinates,4,u);Check(options.Count==3&&PathFinder.Paths==0,"flight never acquires naval research restriction");});
   Test("WATER-027 duplicate Swim destinations share route",()=>{var(s,u,p)=Make();Add(s,0,1,Terrain.Type.Field);PathFinder.CachedOptions=Coords(new(0,1),new(0,1),new(0,1));var output=PathFinder.GetMoveOptions(s,u.coordinates,4,u);Check(output.Count==3&&PathFinder.Paths==1,"one bounded route per distinct offered endpoint");});
   Test("WATER-028 same-turn research re-evaluates native permissions",()=>{var(s,u,p)=Make();Check(!Goes(s,u,1),"before research");p.Techs.Add(Tech.Type.Fishing);Check(Goes(s,u,1),"next query sees research immediately");p.Techs.Remove(Tech.Type.Fishing);Check(!Goes(s,u,1),"no stale positive permission cache");});
   Test("WATER-029 cleared flying scope rejects late result",()=>{var(s,u,p)=Make("firedragon");object? result=null;NativeMimicWaterMovement.BeforePath(s,u.coordinates,new WorldCoordinates(1,0),u,out var scope,ref result);NativeMimicWaterMovement.Clear();result=Coords(new WorldCoordinates(1,0));NativeMimicWaterMovement.AfterPath(new WorldCoordinates(1,0),scope,ref result);Check(((Il2CppSystem.Collections.Generic.List<WorldCoordinates>)result!).Count==0,"unrestricted old generation cannot publish");NativeMimicWaterMovement.Finished(null,scope);});
   Test("WATER-030 captured Island Swim is preserved by real catalog",()=>{
    string json=System.IO.File.ReadAllText(Environment.GetEnvironmentVariable("DECEPTION_CAPTURED_TREE_FIXTURE")??throw new Exception("captured registry fixture missing"));
    var original=System.Text.Json.Nodes.JsonNode.Parse(json)!;var units=System.Text.Json.Nodes.JsonNode.Parse(RecruitmentCatalog.Add(TechTree.AddDeception(json).Json).Json)!["unitData"]!;
    var native=original["unitData"]!["island"]!;var carrier=units[RecruitmentCatalog.Variant("island")]!;
    Check(native["unitAbilities"]!.AsArray().Any(v=>v!.GetValue<string>()=="swim")&&!native["unitAbilities"]!.AsArray().Any(v=>v!.GetValue<string>()=="fly"),"captured Island has Swim and no Fly");
    Check(carrier["unitAbilities"]!.AsArray().Any(v=>v!.GetValue<string>()=="swim")&&carrier["movementTerrain"]!.ToJsonString()==native["movementTerrain"]!.ToJsonString(),"real carrier copies native movement and Swim shortcut");
    var(s,u,p)=Make();u.Allowed.Clear();u.Allowed.Add(new(){type=Terrain.Type.Water});u.Allowed.Add(new(){type=Terrain.Type.Wetland});
    Check(UnitDataExtensions.GetAllowedTerrain(u,s).Any(t=>t.type==Terrain.Type.Water),"audited native Swim result has Water before research outside movement scope");Check(!Goes(s,u,1),"adapter closes that early recruitment shortcut");p.Techs.Add(Tech.Type.Fishing);Check(Goes(s,u,1),"researched native Water retained");
   });
   Test("WATER-031 flooded source destination and route",()=>{var(s,u,p)=Make();s.Map.Tiles[u.coordinates].terrain=Terrain.Type.Ocean;s.Map.Tiles[u.coordinates].Flooded=true;s.Map.Tiles[new(1,0)].Flooded=true;s.Map.Tiles[new(2,0)].Flooded=true;Check(Goes(s,u,2)&&Command(s,new(2,0)),"native Wetland alternative at every route position");s.Map.Tiles[new(1,0)].Flooded=false;Check(!Goes(s,u,2),"plain intervening water remains locked");});
   Test("WATER-032 native bridge short route remains legal",()=>{var(s,u,p)=Make();s.Map.Tiles[new(1,0)].improvement=new(){type=Polytopia.Data.ImprovementData.Type.Bridge};s.Map.Tiles[new(2,0)].terrain=Terrain.Type.Field;Add(s,0,1,Terrain.Type.Field);Add(s,1,1,Terrain.Type.Field);Add(s,2,1,Terrain.Type.Field);var route=PathFinder.GetPath(s,u.coordinates,new(2,0),4,u);Check(route.Count==3&&route.Contains(new(1,0)),"native bridge is traversable without naval research");Check(Command(s,new(2,0)),"command agrees");});
   Test("WATER-033 port alone is not a bridge exemption",()=>{var(s,u,p)=Make();s.Map.Tiles[new(1,0)].improvement=new(){type=Polytopia.Data.ImprovementData.Type.Port};s.Map.Tiles[new(1,0)].Port=true;Check(!Goes(s,u,1),"embark improvement does not invent Bridge ability");});
   Test("WATER-034 native bridge direction denial preserved",()=>{var(s,u,p)=Make();s.Map.Tiles[new(1,0)].improvement=new(){type=Polytopia.Data.ImprovementData.Type.Bridge};PathFinder.NativeRoute=(_,_,_,_,_)=>Coords();Check(!Goes(s,u,1),"only native-returned routes accepted; no replacement path invented");});
   Test("WATER-035 detached apparent research matches live rules",()=>{var(s,u,p)=Make();var clone=new UnitState{type=UnitType.island};clone.Allowed.AddRange(u.Allowed);object[] route={new WorldCoordinates(2,0),new WorldCoordinates(1,0),new WorldCoordinates(0,0)};Check(!NativeMimicWaterMovement.AllowsApparentRoute(s,clone,route),"early Swim not enough");p.Techs.Add(Tech.Type.Fishing);Check(!NativeMimicWaterMovement.AllowsApparentRoute(s,clone,route),"deep still locked");p.Techs.Add(Tech.Type.Sailing);Check(NativeMimicWaterMovement.AllowsApparentRoute(s,clone,route),"researched route accepted without replacing actual body");Check(ReferenceEquals(s.Map.Tiles[u.coordinates].unit,u)&&u.health==10&&!u.moved&&!u.attacked,"no actual mutation");});
   Test("WATER-036 detached flying profile bypasses water research",()=>{var(s,u,p)=Make();var clone=new UnitState{type=UnitType.firedragon};Check(NativeMimicWaterMovement.AllowsApparentRoute(s,clone,new object[]{new WorldCoordinates(2,0),new WorldCoordinates(1,0),u.coordinates}),"flight preserves native crossing");});
   Test("WATER-037 detached route preserves wetland and bridge",()=>{var(s,u,p)=Make();var clone=new UnitState{type=UnitType.island};clone.Allowed.AddRange(u.Allowed);s.Map.Tiles[new(1,0)].improvement=new(){type=Polytopia.Data.ImprovementData.Type.Bridge};s.Map.Tiles[new(2,0)].Flooded=true;object[] route={new WorldCoordinates(2,0),new WorldCoordinates(1,0),u.coordinates};Check(NativeMimicWaterMovement.AllowsApparentRoute(s,clone,route),"native alternatives retained");s.Map.Tiles[new(1,0)].improvement=new(){type=Polytopia.Data.ImprovementData.Type.Port};Check(!NativeMimicWaterMovement.AllowsApparentRoute(s,clone,route),"port alone still not a bridge");});
   Test("WATER-038 detached query grants no live scope",()=>{var(s,u,p)=Make();p.Techs.UnionWith(new[]{Tech.Type.Fishing,Tech.Type.Sailing});var clone=new UnitState{type=u.type};clone.Allowed.AddRange(u.Allowed);Check(NativeMimicWaterMovement.AllowsApparentRoute(s,clone,new object[]{new WorldCoordinates(1,0),u.coordinates}),"read-only profile accepted");Check(!Goes(s,clone,1),"unregistered detached carrier cannot become live move authority");Check(ReferenceEquals(UnitDataExtensions.GetAllowedTerrain(u,s),u.Allowed),"no Current scope published");});
   Test("WATER-039 detached missing owner and unbound state rejected",()=>{var(s,u,p)=Make();var clone=new UnitState{type=UnitType.firedragon,owner=9};var route=new object[]{new WorldCoordinates(1,0),u.coordinates};Check(!NativeMimicWaterMovement.AllowsApparentRoute(s,clone,route),"unknown owner");clone.owner=1;s.Owned=false;Check(!NativeMimicWaterMovement.AllowsApparentRoute(s,clone,route),"unbound state");});
   Test("WATER-040 detached city terrain alternative",()=>{var(s,u,p)=Make();var clone=new UnitState{type=UnitType.island};clone.Allowed.AddRange(u.Allowed);s.Map.Tiles[new(1,0)].City=true;Check(NativeMimicWaterMovement.AllowsApparentRoute(s,clone,new object[]{new WorldCoordinates(1,0),u.coordinates}),"city alternative defers to native apparent path accessibility");Check(!Goes(s,u,1),"read-only comparison does not relax true Mimic water gate");});
   Console.WriteLine(JsonSerializer.Serialize(new{passed=true,cases=Tests.Count,assertions=Assertions,tests=Tests,nativeGame="NOT RUN"}));return 0;
  }catch(Exception e){Console.WriteLine(e);return 1;}}
 }
}
